import React, { createContext, useContext, useState, useEffect } from 'react';
import { api } from '../services/api';

const NewsContext = createContext();

export const useNews = () => {
  const context = useContext(NewsContext);
  if (!context) throw new Error('useNews must be used within NewsProvider');
  return context;
};

export const NewsProvider = ({ children }) => {
  const [news, setNews] = useState([]);

  // لود اخبار از API یا localStorage
  useEffect(() => {
    loadNews();
  }, []);

  const loadNews = async () => {
    try {
      const data = await api.getNews();
      setNews(data);
      localStorage.setItem('dl-news', JSON.stringify(data));
    } catch (error) {
      // API در دسترس نیست - از localStorage بخون
      const saved = localStorage.getItem('dl-news');
      if (saved) {
        setNews(JSON.parse(saved));
      }
    }
  };

  // ذخیره توی localStorage هر وقت news تغییر کنه
  useEffect(() => {
    if (news.length > 0) {
      localStorage.setItem('dl-news', JSON.stringify(news));
    }
  }, [news]);

  const addNews = async (newsItem) => {
    try {
      const added = await api.addNews(newsItem);
      setNews(prev => [added, ...prev]);
      return added;
    } catch (error) {
      // API نیست - ذخیره محلی
      const newItem = { ...newsItem, id: Date.now(), date: new Date().toISOString().split('T')[0] };
      setNews(prev => [newItem, ...prev]);
      return newItem;
    }
  };

  const updateNews = async (id, updatedItem) => {
    try {
      await api.updateNews(id, updatedItem);
      setNews(prev => prev.map(item => item.id === id ? { ...item, ...updatedItem } : item));
    } catch (error) {
      setNews(prev => prev.map(item => item.id === id ? { ...item, ...updatedItem } : item));
    }
  };

  const deleteNews = async (id) => {
    try {
      await api.deleteNews(id);
    } catch (error) {
      // حذف محلی
    }
    setNews(prev => prev.filter(item => item.id !== id));
  };

  return (
    <NewsContext.Provider value={{ news, addNews, updateNews, deleteNews, loadNews }}>
      {children}
    </NewsContext.Provider>
  );
};
